// Generates src/api/schema.d.ts from api/openapi.yaml. `--check` fails if the committed file is stale.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

const root = new URL('..', import.meta.url);
const spec = new URL('api/openapi.yaml', root);
const out = fileURLToPath(new URL('src/api/schema.d.ts', root));

const ast = await openapiTS(spec, { defaultNonNullable: false });
const body =
  '/* eslint-disable */\n// GENERATED by scripts/gen-api.mjs from api/openapi.yaml. Do not edit by hand.\n\n' +
  astToString(ast);

if (process.argv.includes('--check')) {
  const current = existsSync(out) ? readFileSync(out, 'utf8') : '';
  if (current !== body) {
    console.error('src/api/schema.d.ts is stale: run `npm run gen:api`');
    process.exit(1);
  }
  console.log('api schema up to date');
} else {
  writeFileSync(out, body);
  console.log(`wrote ${out}`);
}
